struct Error { std::string field, message; };

std::vector<Error> validate(const BookingRequest& req) {
    std::vector<Error> errors;
    if (req.seats < 1 || req.seats > 20)
        errors.push_back({"seats", "must be between 1 and 20"});
    if (req.date.empty())
        errors.push_back({"date", "is missing"});
    return errors;                       // caller renders all of them
}

