std::expected<Booking, std::vector<Error>> validate(const BookingDto& d) {
    std::vector<Error> errors;
    auto seats = parse_seats(d.seats);           // no early return
    if (!seats) errors.push_back({"seats", "must be a positive integer"});
    if (d.date.empty()) errors.push_back({"date", "is missing"});
    if (!errors.empty()) return std::unexpected(std::move(errors));
    return Booking{*seats, d.date};
}
